with dim_totals as (select e.job_title as employee_job_title, e.level as employee_level, count(*) as rows_total, min(a.salary) as min_salary, grouping_id() as level_id from employees a inner join employees e on a.manager_id = e.id group by grouping sets ((e.job_title, e.level), (e.job_title))) select employee_job_title, employee_level, min_salary, level_id, case when employee_job_title rlike '^(Manager|Analyst)$' then 'GROUP_B' when employee_job_title rlike '^(Engineer|Director)$' then 'CORE' else 'GROUP_A' end as employee_job_title_zone from dim_totals order by employee_job_title_zone desc nulls last, employee_job_title
